inline std::pair<std::size_t, std::uint32_t> TopologicalInitialFifoAvx2(const std::uint32_t* degree, std::vector<int>& order, std::size_t n) {
    static constexpr auto controls = [] {
        std::array<std::array<std::uint8_t, 9>, 256> table{};
