#include <numeric>
#include <random>
#include <vector>
using Graph=std::vector<std::vector<int>>;
static Graph make_graph(int n,int mode){Graph g(n);std::mt19937 rng(733517);auto edge=[&](int a,int b){g[a].push_back(b);};
 if(mode==1)for(int i=1;i<n;++i)edge(i-1,i);
 if(mode==2)for(int i=1;i<n;++i)edge(i,i-1);
 if(mode==3)for(int i=1;i<n;++i)edge(0,i);
 if(mode==4)for(int i=0;i+1<n;++i)edge(i,n-1);
 if(mode==5)for(int i=n/2;i<n;++i)for(int k=0;k<3&&n/2;++k)edge(int((std::uint64_t(i)*17+k*31)%(n/2)),i);
 if(mode==6)for(int i=1;i<n;++i){edge(int(rng()%i),i);if(i%3==0)edge(int(rng()%i),i);}
 if(mode==7)for(int i=1;i<n;++i){edge(i-1,i);edge(i-1,i);}
 if(mode==8&&n){for(int i=1;i<n;++i)edge(i-1,i);edge(n-1,0);}
 if(mode==9){for(int i=1;i<n/2;++i)edge(i-1,i);if(n>1){for(int i=n/2+1;i<n;++i)edge(i-1,i);edge(n-1,n/2);}}
 if(mode==10)for(int i=1;i<n;++i)if(i%4)edge(int(rng()%i),i);
 if(mode==11)for(int i=0;i<n;++i)for(int k=1;k<=16&&i+k<n;++k)edge(i,i+k);
 if(mode==6||mode==10||mode==11){std::vector<int>p(n);std::iota(p.begin(),p.end(),0);std::shuffle(p.begin(),p.end(),rng);Graph z(n);for(int i=0;i<n;++i)for(int t:g[i])z[p[i]].push_back(p[t]);g.swap(z);}
 return g;}
int main(int argc,char**argv){if(argc!=3)return 2;int n=std::atoi(argv[1]),mode=std::atoi(argv[2]);auto g=make_graph(n,mode);std::size_t m=0;std::vector<std::size_t>d(n);for(auto&r:g){m+=r.size();for(int to:r)++d[to];}std::deque<int>q;for(int i=0;i<n;++i)if(!d[i])q.push_back(i);std::vector<int>dp(n);int best=0,seen=0;while(!q.empty()){int x=q.front();q.pop_front();++seen;best=std::max(best,dp[x]);for(int to:g[x]){dp[to]=std::max(dp[to],dp[x]+1);if(--d[to]==0)q.push_back(to);}}if(seen!=n)return 3;std::printf("%d %zu\n",n,m);for(int i=0;i<n;++i)for(int to:g[i])std::printf("%d %d\n",i+1,to+1);bool distinct=true;for(const auto& row:g){auto sorted=row;std::sort(sorted.begin(),sorted.end());distinct&=std::adjacent_find(sorted.begin(),sorted.end())==sorted.end();}std::fprintf(stderr,"%d %d\n",best,int(distinct));}
